import { AdapterRegistry } from "../core/AdapterRegistry.mjs";
import { LogUtil } from "../utils/LogUtil.mjs";

const DEFAULT_ICON = "icons/svg/aura.svg";
const CONDITION_TYPE_META_KEYS = ["lastIconTheme", "iconDir"];

/**
 * The list of status effects the bar can apply. The adapter's conditions section may replace the
 * source list; otherwise CONFIG.statusEffects is used, with a fallback to the system's
 * conditionTypes table. Entries are normalised to carry id, displayName and iconPath.
 * @module conditions/StatusEffectCatalog
 */
export class StatusEffectCatalog {
  /**
   * Raw effects from the adapter, core config or system condition table
   * @returns {Object[]}
   */
  static #getSourceEffects() {
    const adapterSource = AdapterRegistry.active.conditions?.getStatusEffects;
    if (typeof adapterSource === "function") {
      return adapterSource() ?? [];
    }
    if (Array.isArray(CONFIG.statusEffects) && CONFIG.statusEffects.length > 0) {
      return [...CONFIG.statusEffects];
    }
    return this.#getSystemConditionTypes();
  }

  /**
   * Effects derived from CONFIG.<SYSTEM>.conditionTypes when the core list is empty
   * @returns {Object[]}
   */
  static #getSystemConditionTypes() {
    const systemConfig = CONFIG[game.system.id.toUpperCase()];
    const conditionTypes = systemConfig?.conditionTypes;
    if (!conditionTypes) return [];
    const iconDir = systemConfig.statusEffects?.iconDir || `systems/${game.system.id}/icons/conditions`;
    return Object.entries(conditionTypes)
      .filter(([key]) => !CONDITION_TYPE_META_KEYS.includes(key))
      .map(([slug, nameKey]) => ({
        id: slug,
        slug,
        name: nameKey,
        icon: `${iconDir}/${slug}.webp`,
        img: `${iconDir}/${slug}.webp`
      }));
  }

  /**
   * Add display fields to a raw effect
   * @param {Object} effect
   * @returns {Object}
   */
  static #normalise(effect) {
    const rawName = effect.name || effect.label || effect.id || "Unknown";
    return {
      ...effect,
      id: effect.id || effect.slug || effect._id,
      displayName: game.i18n.localize(rawName) || rawName,
      iconPath: effect.img || effect.icon || effect.texture?.src || DEFAULT_ICON
    };
  }

  /**
   * Normalised status effects, deduplicated by id and sorted by display name
   * @returns {Array<Object & {id: string, displayName: string, iconPath: string}>}
   */
  static getStatusEffects() {
    try {
      const mapped = this.#getSourceEffects()
        .map(effect => this.#normalise(effect))
        .filter(effect => effect.displayName && effect.id);
      const unique = Array.from(new Map(mapped.map(effect => [effect.id, effect])).values());
      return unique.sort((a, b) => a.displayName.localeCompare(b.displayName, undefined, { sensitivity: "base" }));
    } catch (error) {
      LogUtil.error("StatusEffectCatalog.getStatusEffects", [error]);
      return [];
    }
  }

  /**
   * One normalised status effect by id
   * @param {string} id
   * @returns {Object|null}
   */
  static getStatusEffect(id) {
    if (!id) return null;
    return this.getStatusEffects().find(effect => effect.id === id) ?? null;
  }
}
