import { getSettings } from "../constants/Settings.mjs";
import { SettingsUtil } from "../utils/SettingsUtil.mjs";
import { LogUtil } from "../utils/LogUtil.mjs";

/**
 * Targets the tokens inside a measured template as it is drawn or moved.
 * Setting values: 1 targets every token, 2 targets non-friendly tokens (disposition <= 0), 3 disables.
 * @module tokens/TemplateAutoTarget
 */
export class TemplateAutoTarget {
  static #throttleTimers = {};
  static #throttleMs = 50;

  /**
   * Maximum disposition to target for the current setting, or null when disabled
   * @returns {number|null}
   */
  static getMaxDisposition() {
    const mode = SettingsUtil.get(getSettings().templateAutoTarget.tag);
    if (mode === 1) return 3;
    if (mode === 2) return 0;
    return null;
  }

  /**
   * Throttled refreshMeasuredTemplate handler, for templates the current user placed
   * @param {MeasuredTemplate} template
   * @param {Object} options
   */
  static onRefreshMeasuredTemplate(template, options) {
    if (template.document?.author !== game.user) return;
    const key = template.id;
    if (this.#throttleTimers[key]) {
      clearTimeout(this.#throttleTimers[key]);
    }
    this.#throttleTimers[key] = setTimeout(() => {
      delete this.#throttleTimers[key];
      this.targetTokensInTemplate(template);
    }, this.#throttleMs);
  }

  /**
   * Replace the user's targets with the tokens inside the template
   * @param {MeasuredTemplate} template
   */
  static targetTokensInTemplate(template) {
    const maxDisposition = this.getMaxDisposition();
    if (maxDisposition === null || !template.shape) return;
    this.#applyTargets(canvas.tokens.placeables.filter(token =>
      token.document.disposition <= maxDisposition
      && template.shape.contains(token.center.x - template.x, token.center.y - template.y)
    ));
  }

  /**
   * Replace the user's targets with the tokens inside any of the regions. For systems that place
   * area templates as Region documents; the host calls it from the system's own hook.
   * @param {RegionDocument[]} regions
   * @returns {Token[]} The tokens targeted
   */
  static targetTokensInRegions(regions) {
    const maxDisposition = this.getMaxDisposition();
    if (maxDisposition === null || !regions?.length) return [];
    const tokens = canvas.tokens.placeables.filter(token =>
      token.document.disposition <= maxDisposition
      && regions.some(region => this.isTokenInsideRegion(token, region))
    );
    this.#applyTargets(tokens);
    return tokens;
  }

  /**
   * Whether a token is inside a region, using Foundry's own containment test so the result matches
   * what the region considers inside. On v14 that test covers the token's footprint, level and
   * elevation, so a token is found even when its center sits on the region's edge; on v13 it is a
   * center point test. Falls back to a center point test when the method is missing or throws.
   * @param {Token} token
   * @param {RegionDocument} region
   * @returns {boolean}
   */
  static isTokenInsideRegion(token, region) {
    try {
      if (typeof token.document?.testInsideRegion === "function") return token.document.testInsideRegion(region);
    } catch (error) {
      LogUtil.warn("TemplateAutoTarget.isTokenInsideRegion - containment test failed, using center point", [token.name, error]);
    }
    const point = { x: token.center.x, y: token.center.y, elevation: token.document.elevation ?? 0 };
    return !!(region.testPoint?.(point) || region.object?.testPoint?.(point, point.elevation));
  }

  /**
   * Replace the user's targets with the given tokens and broadcast the change
   * @param {Token[]} tokens
   */
  static #applyTargets(tokens) {
    for (const token of Array.from(game.user.targets)) {
      token.setTarget(false, { releaseOthers: false });
    }
    tokens.forEach((token, i) => {
      token.setTarget(true, { releaseOthers: i === 0, groupSelection: true });
    });
    if (tokens.length > 0) {
      game.user.broadcastActivity({ targets: game.user.targets.ids });
    }
  }
}
