import { MODULE_ID } from "../constants/General.mjs";
import { LogUtil } from "./LogUtil.mjs";

/**
 * General purpose DOM and Foundry helpers
 * @module utils/GeneralUtil
 */
export class GeneralUtil {
  static #styleId = "ftb-vars";

  /**
   * Whether a module is installed and active
   * @param {string} moduleName
   * @returns {boolean}
   */
  static isModuleOn(moduleName) {
    return !!game.modules?.get(moduleName)?.active;
  }

  /**
   * Full rendered width of an element, 0 when not displayed
   * @param {HTMLElement} element
   * @returns {number}
   */
  static getFullWidth(element) {
    const style = window.getComputedStyle(element);
    return style.width === "0px" ? 0 : element.offsetWidth;
  }

  /**
   * Set a CSS custom property on the body through a dedicated style element
   * @param {string} varName
   * @param {string|number} varValue
   */
  static addCSSVars(varName, varValue) {
    let style = document.getElementById(this.#styleId);
    if (!style) {
      style = document.createElement("style");
      style.id = this.#styleId;
      document.head.appendChild(style);
    }
    const vars = this.#parseVars(style.textContent);
    vars[varName] = String(varValue);
    const declarations = Object.entries(vars).map(([name, value]) => `  ${name}: ${value};`).join("\n");
    style.textContent = `body.${MODULE_ID} {\n${declarations}\n}`;
  }

  /**
   * Parse the declarations of the module style element
   * @param {string} cssText
   * @returns {Object<string, string>}
   */
  static #parseVars(cssText) {
    const vars = {};
    const start = cssText.indexOf("{");
    const end = cssText.lastIndexOf("}");
    if (start === -1 || end === -1) {
      return vars;
    }
    cssText.substring(start + 1, end).split(";").forEach(decl => {
      const idx = decl.indexOf(":");
      if (idx === -1) return;
      const name = decl.substring(0, idx).trim();
      const value = decl.substring(idx + 1).trim();
      if (name) vars[name] = value;
    });
    return vars;
  }

  /**
   * Alias for Foundry's Handlebars renderer
   * @param {string} templatePath
   * @param {Object} data
   * @returns {Promise<string>}
   */
  static renderTemplate(templatePath, data) {
    return foundry.applications.handlebars.renderTemplate(templatePath, data);
  }

  /**
   * Alias for Foundry's Handlebars loader
   * @param {string|string[]|Object<string, string>} templatePaths - Paths, or partial names mapped to paths
   * @returns {Promise<Object>}
   */
  static loadTemplates(templatePaths) {
    const paths = typeof templatePaths === "string" ? [templatePaths] : templatePaths;
    return foundry.applications.handlebars.loadTemplates(paths);
  }

  /**
   * Find the player user owning an actor, preferring connected users
   * @param {Actor} actor
   * @returns {User|null}
   */
  static getActorOwner(actor) {
    if (!actor) return null;
    const isOwner = user => !user.isGM
      && (actor.ownership?.[user.id] ?? CONST.DOCUMENT_OWNERSHIP_LEVELS.NONE) >= CONST.DOCUMENT_OWNERSHIP_LEVELS.OWNER;
    return game.users.find(user => user.active && isOwner(user)) ?? game.users.find(isOwner) ?? null;
  }

  /**
   * Whether any modifier key that usually skips dialogs is pressed
   * @param {Event|null} event
   * @returns {boolean}
   */
  static areSkipKeysPressed(event) {
    if (!event) return false;
    return !!(event.shiftKey || event.altKey || event.ctrlKey || event.metaKey);
  }

  /**
   * Adjust the menu offset variable so the docked menu sits next to the chat controls
   */
  static adjustMenuOffset() {
    const chatControls = document.querySelector("#chat-notifications #roll-privacy, #chat-notifications #message-modes");
    const controlItemSize = parseInt(getComputedStyle(document.documentElement).getPropertyValue("--control-item-size")) || 36;
    const controlsWidth = chatControls ? this.getFullWidth(chatControls) : controlItemSize;
    const isCrlngnUIOn = !!document.querySelector("body.crlngn-tabs");
    this.addCSSVars("--ftb-menu-offset", `${isCrlngnUIOn ? controlsWidth : controlsWidth + 16}px`);
  }

  /**
   * Whether the sidebar is expanded
   * @returns {boolean}
   */
  static isSidebarExpanded() {
    return ui?.sidebar?.expanded || false;
  }

  /**
   * Mirror the sidebar state on the body and write --current-sidebar-width through the module style
   * element. Foundry v14 loads module styles into the "modules" cascade layer, so a module that injects
   * an unlayered stylesheet overrides them regardless of specificity; if it assigns this variable an
   * invalid value the docked menu loses its offset and ends up under the sidebar
   * @param {boolean} isExpanded
   */
  static updateSidebarClass(isExpanded) {
    document.body.classList.toggle("flash-sidebar-expanded", !!isExpanded);
    this.addCSSVars("--current-sidebar-width", isExpanded ? "var(--sidebar-width, 200px)" : "0px");
    this.adjustMenuOffset();
  }

  /**
   * Confirmation dialog asking to reload the page
   * @param {string} title
   * @param {string} content
   * @returns {Promise<boolean>}
   */
  static confirmReload(title, content) {
    return foundry.applications.api.DialogV2.confirm({
      window: { title },
      content,
      yes: { callback: () => { window.location.reload(); return true; } },
      no: { callback: () => false },
      rejectClose: false
    });
  }

  /**
   * Log and swallow errors from optional integrations
   * @param {string} label
   * @param {Function} fn
   * @returns {*}
   */
  static tryCall(label, fn) {
    try {
      return fn();
    } catch (error) {
      LogUtil.error(label, [error]);
      return undefined;
    }
  }
}
