/**
 * Icon configurations for a type
 * @param {string} type - One of ICON_TYPES
 * @returns {Object}
 */
export function getIconConfigurations(type) {
  switch (type) {
    case ICON_TYPES.MODULE_ACTIONS:
      return MODULE_ACTION_ICONS;
    case ICON_TYPES.ACTOR_ACTIONS:
      return ACTOR_ACTION_ICONS;
    default:
      return {};
  }
}

/**
 * Single icon configuration
 * @param {string} iconId
 * @param {string} type - One of ICON_TYPES
 * @returns {Object|null}
 */
export function getIconConfiguration(iconId, type) {
  return getIconConfigurations(type)[iconId] ?? null;
}

/**
 * Default order and enabled state of every icon
 * @returns {{moduleActions: Array, actorActions: Array}}
 */
export function getDefaultIconLayout() {
  const layout = { moduleActions: [], actorActions: [] };
  Object.values(MODULE_ACTION_ICONS).forEach((icon, order) => {
    layout.moduleActions.push({ id: icon.id, icon: icon.icon, enabled: true, order });
  });
  Object.values(ACTOR_ACTION_ICONS).forEach((icon, order) => {
    layout.actorActions.push({ id: icon.id, icon: icon.icon, enabled: true, order });
  });
  return layout;
}

/**
 * Capability an icon needs, if any
 * @param {string} iconId
 * @param {string} type
 * @returns {string|null}
 */
export function getIconCapability(iconId, type) {
  const config = getIconConfiguration(iconId, type);
  return config?.capability ?? null;
}

/**
 * Whether an icon is reserved for GMs
 * @param {string} iconId
 * @param {string} type
 * @returns {boolean}
 */
export function isIconGMOnly(iconId, type) {
  return !!getIconConfiguration(iconId, type)?.gmOnly;
}

export { CAPABILITIES };
