import { LANG_PREFIX } from "../constants/General.mjs";
import { LogUtil } from "../utils/LogUtil.mjs";
import { ActorResolver } from "../actors/ActorResolver.mjs";
import { ActorClassifier } from "../actors/ActorClassifier.mjs";
import { AdapterRegistry } from "../core/AdapterRegistry.mjs";
import { NotifyUtil } from "../utils/NotifyUtil.mjs";

/**
 * Creates tokens for actors on the canvas, one at a time under the cursor (interactive mode)
 * or all at once at a given location. Group actors expand to their members through the adapter.
 * @module tokens/TokenPlacement
 */
export class TokenPlacement {
  static #isPlacing = false;
  /** @type {Array<{actor: Actor, data: Object}>} */
  static #previews = [];
  static #index = 0;
  static #handlers = null;
  static #rightMouseDown = false;

  /**
   * Enter interactive placement mode for the actors selected in the menu
   * @param {{selectedActors: Set<string>, currentTab: string}} menu
   * @returns {Promise<void>}
   */
  static async placeTokensForSelectedActors(menu) {
    if (!game.user.isGM) {
      NotifyUtil.warn(game.i18n.localize(`${LANG_PREFIX}.notifications.gmOnlyPlacement`));
      return;
    }
    if (menu.selectedActors.size === 0) {
      NotifyUtil.warn(game.i18n.localize(`${LANG_PREFIX}.notifications.noActorsSelectedForPlacement`));
      return;
    }
    if (this.#isPlacing) {
      NotifyUtil.warn(game.i18n.localize(`${LANG_PREFIX}.notifications.placementInProgress`));
      return;
    }

    const actors = await this.#resolveActors(menu.selectedActors);
    if (actors.length === 0) {
      NotifyUtil.warn(game.i18n.localize(`${LANG_PREFIX}.notifications.noActorsSelectedForPlacement`));
      return;
    }

    this.#isPlacing = true;
    this.#index = 0;
    this.#previews = await Promise.all(actors.map(actor => this.#buildPreview(actor)));
    this.#attachHandlers();
    NotifyUtil.info(game.i18n.format(`${LANG_PREFIX}.notifications.placementReady`, { count: actors.length }));
  }

  /**
   * Create tokens for actors centred on a location without user interaction
   * @param {string[]} uniqueIds
   * @param {{x: number, y: number}} location
   * @returns {Promise<TokenDocument[]>}
   */
  static async placeTokensAtLocation(uniqueIds, location) {
    if (!game.user.isGM) {
      NotifyUtil.warn(game.i18n.localize(`${LANG_PREFIX}.notifications.gmOnlyPlacement`));
      return [];
    }
    if (!uniqueIds?.length) {
      NotifyUtil.warn(game.i18n.localize(`${LANG_PREFIX}.notifications.noActorsSelectedForPlacement`));
      return [];
    }
    if (typeof location?.x !== "number" || typeof location?.y !== "number") {
      NotifyUtil.error(game.i18n.localize(`${LANG_PREFIX}.notifications.invalidPlacementLocation`));
      return [];
    }

    const actors = await this.#resolveActors(uniqueIds);
    if (actors.length === 0) {
      NotifyUtil.warn(game.i18n.localize(`${LANG_PREFIX}.notifications.noActorsSelectedForPlacement`));
      return [];
    }

    const snapped = canvas.grid.getSnappedPoint(location, { mode: CONST.GRID_SNAPPING_MODES.CENTER });
    const created = [];
    for (const actor of actors) {
      const preview = await this.#buildPreview(actor);
      try {
        const docs = await canvas.scene.createEmbeddedDocuments("Token", [this.#tokenDataAt(preview.data, snapped)]);
        created.push(...docs);
      } catch (error) {
        LogUtil.error("TokenPlacement: failed to create token", [error, preview.actor.name]);
      }
    }
    return created;
  }

  /**
   * Whether interactive placement mode is active
   * @returns {boolean}
   */
  static isPlacing() {
    return this.#isPlacing;
  }

  /**
   * Leave placement mode
   */
  static cancel() {
    if (!this.#isPlacing) return;
    this.#cleanup();
    NotifyUtil.info(game.i18n.localize(`${LANG_PREFIX}.notifications.tokenPlacementCancelled`));
  }

  /**
   * Actors to place for a set of unique ids, expanding groups into their members
   * @param {Iterable<string>} uniqueIds
   * @returns {Promise<Actor[]>}
   */
  static async #resolveActors(uniqueIds) {
    const actors = [];
    const groups = AdapterRegistry.active.groups;
    for (const uniqueId of uniqueIds) {
      const actor = ActorResolver.getActor(uniqueId);
      if (!actor) {
        LogUtil.warn("TokenPlacement: no actor for id", [uniqueId]);
        continue;
      }
      if (ActorClassifier.isGroupActor(actor) && groups?.getGroupMembers) {
        const members = await groups.getGroupMembers(actor);
        for (const member of members ?? []) {
          if (member?.actor) actors.push(member.actor);
        }
      } else {
        actors.push(actor);
      }
    }
    return actors;
  }

  /**
   * Prototype token data for an actor
   * @param {Actor} actor
   * @returns {Promise<{actor: Actor, data: Object}>}
   */
  static async #buildPreview(actor) {
    const baseActor = actor.isToken ? actor.baseActor : actor;
    const tokenDoc = await baseActor.getTokenDocument();
    return { actor: baseActor, data: { ...tokenDoc.toObject(), x: 0, y: 0, alpha: 0.5, actorLink: false } };
  }

  /**
   * Token creation data centred on a grid point
   * @param {Object} data - Prototype token data
   * @param {{x: number, y: number}} center
   * @returns {Object}
   */
  static #tokenDataAt(data, center) {
    const gridSize = canvas.grid.size;
    return {
      ...data,
      x: center.x - (data.width * gridSize) / 2,
      y: center.y - (data.height * gridSize) / 2,
      alpha: 1,
      actorLink: false
    };
  }

  /**
   * Snapped grid center under the cursor
   * @param {PIXI.FederatedPointerEvent} event
   * @returns {{x: number, y: number}}
   */
  static #cursorCenter(event) {
    const position = event.getLocalPosition ? event.getLocalPosition(canvas.tokens) : event.data.getLocalPosition(canvas.tokens);
    return canvas.grid.getSnappedPoint({ x: position.x, y: position.y }, { mode: CONST.GRID_SNAPPING_MODES.CENTER });
  }

  /**
   * Attach canvas listeners for placement mode
   */
  static #attachHandlers() {
    this.#handlers = {
      mousemove: event => this.#onMouseMove(event),
      click: event => this.#onClick(event),
      rightclick: event => this.#onRightClick(event),
      rightdown: () => { this.#rightMouseDown = true; },
      rightup: () => { this.#rightMouseDown = false; }
    };
    for (const [name, handler] of Object.entries(this.#handlers)) {
      canvas.stage.on(name, handler);
    }
  }

  /**
   * Draw the ghost of the current token and a progress label under the cursor
   * @param {PIXI.FederatedPointerEvent} event
   * @returns {Promise<void>}
   */
  static async #onMouseMove(event) {
    if (!this.#isPlacing || this.#index >= this.#previews.length) return;
    const snapped = this.#cursorCenter(event);
    this.#clearGraphics();
    if (!canvas.controls) return;

    const data = this.#previews[this.#index].data;
    const gridSize = canvas.grid.size;
    const width = data.width * gridSize;
    const height = data.height * gridSize;
    try {
      const texture = await foundry.canvas.loadTexture(data.texture.src);
      const ghost = new PIXI.Sprite(texture);
      ghost.anchor.set(0);
      ghost.x = snapped.x - width / 2;
      ghost.y = snapped.y - height / 2;
      ghost.width = width;
      ghost.height = height;
      ghost.alpha = 0.5;
      ghost.tint = 0x00ccff;
      ghost._flashTokenBarPlacementPreview = true;
      canvas.controls.addChild(ghost);

      const label = new PIXI.Text(`${this.#index + 1}/${this.#previews.length}`, {
        fontSize: 20, fill: 0xffffff, stroke: 0x000000, strokeThickness: 4
      });
      label.anchor.set(0.5);
      label.x = snapped.x;
      label.y = snapped.y - height / 2 - 20;
      label._flashTokenBarPlacementPreview = true;
      canvas.controls.addChild(label);
    } catch (error) {
      LogUtil.warn("TokenPlacement: error drawing placement preview", [error]);
    }
  }

  /**
   * Create the current token at the clicked grid point and advance
   * @param {PIXI.FederatedPointerEvent} event
   * @returns {Promise<void>}
   */
  static async #onClick(event) {
    if (!this.#isPlacing || this.#index >= this.#previews.length) return;
    const snapped = this.#cursorCenter(event);
    const preview = this.#previews[this.#index];
    try {
      await canvas.scene.createEmbeddedDocuments("Token", [this.#tokenDataAt(preview.data, snapped)]);
      this.#index++;
      if (this.#index >= this.#previews.length) {
        const total = this.#previews.length;
        this.#cleanup();
        NotifyUtil.info(game.i18n.format(`${LANG_PREFIX}.notifications.tokensPlaced`, { count: total }));
      }
    } catch (error) {
      LogUtil.error("TokenPlacement: failed to create token", [error, preview.actor.name]);
    }
  }

  /**
   * Skip the current token; leaves placement mode when none remain
   * @param {PIXI.FederatedPointerEvent} event
   */
  static #onRightClick(event) {
    if (!this.#isPlacing || this.#index >= this.#previews.length || this.#rightMouseDown) return;
    event.stopPropagation();
    this.#previews.splice(this.#index, 1);
    if (this.#previews.length === 0 || this.#index >= this.#previews.length) {
      this.cancel();
    } else {
      this.#clearGraphics();
    }
  }

  /**
   * Remove ghost graphics from the controls layer
   */
  static #clearGraphics() {
    if (!canvas.controls?.children) return;
    try {
      for (const child of Array.from(canvas.controls.children)) {
        if (!child._flashTokenBarPlacementPreview) continue;
        canvas.controls.removeChild(child);
        child.destroy?.();
      }
    } catch (error) {
      LogUtil.warn("TokenPlacement: error clearing preview graphics", [error]);
    }
  }

  /**
   * Detach listeners and reset state
   */
  static #cleanup() {
    this.#isPlacing = false;
    this.#previews = [];
    this.#index = 0;
    this.#rightMouseDown = false;
    if (this.#handlers) {
      for (const [name, handler] of Object.entries(this.#handlers)) {
        canvas.stage?.off(name, handler);
      }
      this.#handlers = null;
    }
    this.#clearGraphics();
  }
}
