import { AdapterRegistry } from "../core/AdapterRegistry.mjs";
import { TABS } from "../constants/General.mjs";

/**
 * Decides which tab an actor belongs to. Ownership drives the PC / NPC split in every system;
 * the adapter's actorTypes section only decides which actor types are listed and which are groups.
 * @module actors/ActorClassifier
 */
export class ActorClassifier {
  /**
   * Whether a non-GM user owns the actor
   * @param {Actor} actor
   * @returns {boolean}
   */
  static isPlayerOwned(actor) {
    if (!actor) return false;
    return Object.entries(actor.ownership ?? {}).some(([userId, level]) => {
      if (userId === "default") return false;
      const user = game.users.get(userId);
      return !!user && !user.isGM && level >= CONST.DOCUMENT_OWNERSHIP_LEVELS.OWNER;
    });
  }

  /**
   * Whether the adapter treats the actor type as a group
   * @param {Actor} actor
   * @returns {boolean}
   */
  static isGroupActor(actor) {
    const adapter = AdapterRegistry.active;
    if (adapter.groups?.isGroupActor) {
      return !!adapter.groups.isGroupActor(actor);
    }
    const groupTypes = adapter.actorTypes?.group ?? [];
    return groupTypes.includes(actor?.type);
  }

  /**
   * Whether the actor type should appear in the bar at all
   * @param {Actor} actor
   * @returns {boolean}
   */
  static isListed(actor) {
    if (!actor) return false;
    if (this.isGroupActor(actor)) return true;
    const listed = AdapterRegistry.active.actorTypes?.listed;
    if (!listed) return true;
    return listed.includes(actor.type);
  }

  /**
   * Tab for an actor
   * @param {Actor} actor
   * @returns {string} One of TABS
   */
  static classify(actor) {
    if (this.isGroupActor(actor)) return TABS.GROUP;
    return this.isPlayerOwned(actor) ? TABS.PC : TABS.NPC;
  }
}
