import { CAPABILITIES } from "../core/Capabilities.mjs";

/**
 * Base class every system adapter extends. Each optional section unlocks a capability;
 * an adapter that provides nothing still runs with the module's Tier 0 behaviour.
 *
 * Sections (all optional): stats, rolls, groups, conditions, actorTypes, activateHooks().
 * See core/Capabilities.mjs for the shape of each section.
 * @module adapters/SystemAdapter
 */
export class SystemAdapter {
  /**
   * @param {Object} [config]
   * @param {string} [config.id] - Game system id this adapter serves
   * @param {string} [config.name] - Display name
   */
  constructor(config = {}) {
    this.id = config.id ?? this.constructor.systemId ?? null;
    this.name = config.name ?? this.constructor.systemName ?? this.id;
    this.stats = config.stats ?? null;
    this.rolls = config.rolls ?? null;
    this.groups = config.groups ?? null;
    this.conditions = config.conditions ?? null;
    this.actorTypes = config.actorTypes ?? null;
    if (typeof config.activateHooks === "function") {
      this.activateHooks = config.activateHooks;
    }
  }

  /**
   * Game system id served by this adapter class. Subclasses override.
   * @type {string|null}
   */
  static systemId = null;

  /**
   * Display name of the system. Subclasses override.
   * @type {string|null}
   */
  static systemName = null;

  /**
   * Capabilities provided by this adapter, derived from the sections it defines
   * @returns {string[]}
   */
  get capabilities() {
    const caps = [];
    if (this.stats) caps.push(CAPABILITIES.STATS);
    if (this.rolls) caps.push(CAPABILITIES.ROLLS);
    if (this.groups) caps.push(CAPABILITIES.GROUPS);
    if (this.conditions) caps.push(CAPABILITIES.CONDITIONS);
    if (this.actorTypes) caps.push(CAPABILITIES.ACTOR_TYPES);
    if (typeof this.activateHooks === "function") caps.push(CAPABILITIES.HOOKS);
    return caps;
  }

  /**
   * Whether this adapter provides a capability
   * @param {string} capability
   * @returns {boolean}
   */
  has(capability) {
    return this.capabilities.includes(capability);
  }

  /**
   * Called once during setup after the adapter is chosen. Register system hooks here.
   */
  activateHooks() {}

  /**
   * Normalise anything adapter-like into a SystemAdapter instance
   * @param {SystemAdapter|Function|Object} adapterLike
   * @returns {SystemAdapter}
   */
  static from(adapterLike) {
    if (adapterLike instanceof SystemAdapter) {
      return adapterLike;
    }
    if (typeof adapterLike === "function") {
      return new adapterLike();
    }
    return new SystemAdapter(adapterLike);
  }
}
