import { getSettings } from "../../constants/Settings.mjs";
import { SettingsUtil } from "../../utils/SettingsUtil.mjs";
import { ActorResolver } from "../ActorResolver.mjs";
import { HOOKS_MODULE } from "../../constants/Hooks.mjs";

/**
 * GM-defined actor groups stored in a world setting. Available in every system.
 * A member remembers its actor and, for unlinked tokens, the scene and token it came from.
 * @module actors/groups/SavedGroups
 */
export class SavedGroups {
  /**
   * @typedef {Object} SavedGroupMember
   * @property {string} actorId
   * @property {string|null} tokenId
   * @property {string|null} sceneId
   */

  /**
   * @typedef {Object} SavedGroup
   * @property {string} id
   * @property {string} name
   * @property {string} [img]
   * @property {SavedGroupMember[]} members
   */

  /**
   * All saved groups
   * @returns {SavedGroup[]}
   */
  static all() {
    const SETTINGS = getSettings();
    const stored = SettingsUtil.get(SETTINGS.savedGroups.tag) ?? {};
    return Object.values(stored).sort((a, b) => a.name.localeCompare(b.name));
  }

  /**
   * One saved group
   * @param {string} groupId
   * @returns {SavedGroup|null}
   */
  static get(groupId) {
    const SETTINGS = getSettings();
    const stored = SettingsUtil.get(SETTINGS.savedGroups.tag) ?? {};
    return stored[groupId] ?? null;
  }

  /**
   * Create a group from unique ids currently in the bar
   * @param {string} name
   * @param {Iterable<string>} uniqueIds
   * @returns {Promise<SavedGroup|null>}
   */
  static async create(name, uniqueIds) {
    const members = this.membersFromUniqueIds(uniqueIds);
    if (members.length === 0) return null;
    const group = { id: foundry.utils.randomID(), name, img: this.#firstImage(members), members };
    await this.#save({ ...(this.#stored()), [group.id]: group });
    return group;
  }

  /**
   * Replace the members of a group
   * @param {string} groupId
   * @param {Iterable<string>} uniqueIds
   * @returns {Promise<void>}
   */
  static async setMembers(groupId, uniqueIds) {
    const stored = this.#stored();
    if (!stored[groupId]) return;
    stored[groupId].members = this.membersFromUniqueIds(uniqueIds);
    await this.#save(stored);
  }

  /**
   * Rename a group
   * @param {string} groupId
   * @param {string} name
   * @returns {Promise<void>}
   */
  static async rename(groupId, name) {
    const stored = this.#stored();
    if (!stored[groupId]) return;
    stored[groupId].name = name;
    await this.#save(stored);
  }

  /**
   * Delete a group
   * @param {string} groupId
   * @returns {Promise<void>}
   */
  static async remove(groupId) {
    const stored = this.#stored();
    delete stored[groupId];
    await this.#save(stored);
  }

  /**
   * Convert unique ids into stored member records
   * @param {Iterable<string>} uniqueIds
   * @returns {SavedGroupMember[]}
   */
  static membersFromUniqueIds(uniqueIds) {
    const members = [];
    for (const participant of ActorResolver.resolveParticipants(uniqueIds)) {
      const linked = participant.tokenDoc ? participant.tokenDoc.actorLink : true;
      members.push({
        actorId: participant.actorId,
        tokenId: linked ? null : participant.tokenId,
        sceneId: linked ? null : (game.scenes.current?.id ?? null)
      });
    }
    return members;
  }

  /**
   * Resolve stored members into participants for the current scene.
   * Linked members use their scene tokens when present, otherwise the actor itself.
   * @param {SavedGroup} group
   * @returns {import("../ActorResolver.mjs").Participant[]}
   */
  static resolveMembers(group) {
    const participants = [];
    const seen = new Set();
    const sceneId = game.scenes.current?.id;
    for (const member of group.members ?? []) {
      const actor = game.actors.get(member.actorId);
      if (!actor) continue;
      let entries = [];
      if (member.tokenId && member.sceneId === sceneId) {
        const tokenDoc = ActorResolver.getTokenDocument(member.tokenId);
        if (tokenDoc) entries = [ActorResolver.participantFromActor(actor, tokenDoc)];
      } else if (!member.tokenId) {
        const tokens = ActorResolver.getSceneTokens(actor.id);
        entries = tokens.length > 0
          ? tokens.map(tokenDoc => ActorResolver.participantFromActor(actor, tokenDoc))
          : [ActorResolver.participantFromActor(actor, null)];
      }
      for (const entry of entries) {
        if (entry && !seen.has(entry.uniqueId)) {
          seen.add(entry.uniqueId);
          participants.push(entry);
        }
      }
    }
    return participants;
  }

  /**
   * @returns {Object<string, SavedGroup>}
   */
  static #stored() {
    const SETTINGS = getSettings();
    return foundry.utils.deepClone(SettingsUtil.get(SETTINGS.savedGroups.tag) ?? {});
  }

  /**
   * @param {Object<string, SavedGroup>} stored
   * @returns {Promise<void>}
   */
  static async #save(stored) {
    const SETTINGS = getSettings();
    await SettingsUtil.set(SETTINGS.savedGroups.tag, stored);
    Hooks.callAll(HOOKS_MODULE.REFRESH_MENU);
  }

  /**
   * @param {SavedGroupMember[]} members
   * @returns {string}
   */
  static #firstImage(members) {
    const actor = game.actors.get(members[0]?.actorId);
    return actor?.img ?? "icons/svg/mystery-man.svg";
  }
}
